'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const KEY='bilim-pro-v1';
const LAB_IDS=['binary','sorting','pixels','robot','graph','ohm'];
const CUSTOM_ID=/^t-[a-z0-9]{6,20}$/;
const fresh=()=>({version:1,completed:[],solved:[],quiz:{},history:[],labs:[],grade:7,subject:'informatics'});
const knownLesson=x=>typeof x==='string'&&(LESSONS.some(l=>l.id===x)||CUSTOM_ID.test(x));
function cleanState(v){
 const out=fresh();if(!v||v.version!==1)return out;
 out.completed=[...new Set((Array.isArray(v.completed)?v.completed:[]).filter(knownLesson))];
 out.solved=[...new Set((Array.isArray(v.solved)?v.solved:[]).filter(x=>Number.isInteger(x)&&x>=0&&x<CHALLENGES.length))];
 out.labs=[...new Set((Array.isArray(v.labs)?v.labs:[]).filter(x=>LAB_IDS.includes(x)))];
 if(v.quiz&&typeof v.quiz==='object')Object.entries(v.quiz).forEach(([k,n])=>{if(knownLesson(k)&&Number.isInteger(n)&&n>=0&&n<=10)out.quiz[k]=n;});
 out.history=(Array.isArray(v.history)?v.history:[]).filter(x=>x&&Number.isInteger(x.score)&&x.score>=0&&Number.isFinite(x.time)&&Number.isFinite(x.date)&&x.date>0).map(x=>({score:x.score,total:Number.isInteger(x.total)&&x.total>0&&x.total<=60?x.total:30,subject:SUBJECTS.some(s=>s.id===x.subject)?x.subject:'informatics',time:Math.min(5400,Math.max(0,x.time)),date:x.date})).filter(x=>x.score<=x.total).slice(0,30);
 out.grade=Number.isInteger(v.grade)&&v.grade>=5&&v.grade<=11?v.grade:7;
 out.subject=SUBJECTS.some(s=>s.id===v.subject)?v.subject:'informatics';return out;
}
let state;try{state=cleanState(JSON.parse(localStorage.getItem(KEY)));}catch{state=fresh();}
let storageWarned=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storageWarned){storageWarned=true;toast('Браузер сақтауға рұқсат бермеді. Прогресті JSON ретінде жүктеп ал.');}}if(window.BilimAPI)window.BilimAPI.syncProgress(progressSummary());}
function progressSummary(){return {xp:stats().xp,completed:state.completed,quiz:state.quiz,solved:state.solved.length,labs:state.labs,history:state.history.slice(0,10).map(h=>({score:h.score,total:h.total,date:h.date,subject:h.subject}))};}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.handle);toast.handle=setTimeout(()=>$('#toast').classList.remove('visible'),3500);if(window.BilimMotion)window.BilimMotion.onToast(s);}
const iconPaths={home:'M3 10 12 3l9 7v10H3V10Zm6 10v-7h6v7',courses:'M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-3-2H4V4Zm10 3a3 3 0 0 1 3-3h4v15h-4a4 4 0 0 0-3 2',olympiad:'M8 3h8v6a4 4 0 0 1-8 0V3Zm0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 13v6m-4 2h8',exam:'M7 3h10v3h3v16H4V6h3m0-3v5h10V3M8 12h8m-8 4h5',labs:'M8 3h8M10 3v7L4 20a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1l-6-10V3M7 16h10',progress:'M4 20V10m8 10V4m8 16v-7M2 22h20',teachers:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-7 10v-1a6 6 0 0 1 12 0v1m3-10a3 3 0 1 0 0-6m2 16v-1a5 5 0 0 0-3-4.6',teacher:'M3 7l9-4 9 4-9 4-9-4Zm4 2v5c0 2 2.5 3.5 5 3.5s5-1.5 5-3.5V9m4-2v6',about:'M12 16v-5m0-3v-1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[n]||iconPaths.home}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const PAGES=[['home','Басты бет'],['courses','Сабақтар'],['olympiad','Олимпиада'],['exam','ҰБТ дайындық'],['labs','Зертханалар'],['progress','Менің жетістігім'],['teachers','Мұғалімдер'],['teacher','Кабинет'],['about','Жоба туралы']];
const gradesFor=subject=>[5,6,7,8,9,10,11].filter(g=>LESSONS.some(l=>(!subject||subject==='all'||l.subject===subject)&&l.grade===g));
const gradeTabs=(grade,scope,all=false,subject=null)=>`<div class="grade-tabs" aria-label="Сыныпты таңдау">${(all?[0,...gradesFor(subject)]:gradesFor(subject)).map(g=>`<button data-grade="${g}" data-scope="${scope}" class="${g===grade?'active':''}" aria-pressed="${g===grade}">${g?g+'-сынып':'Барлығы'}</button>`).join('')}</div>`;
const subjectTabs=(current,scope,all=false)=>`<div class="subject-tabs" role="group" aria-label="Пәнді таңдау">${(all?[{id:'all',short:'Барлық пәндер',symbol:'✦',theme:0}]:[]).concat(SUBJECTS).map(s=>`<button data-subject="${s.id}" data-scope="${scope}" class="subject-chip s-${s.id} ${s.id===current?'active':''}" aria-pressed="${s.id===current}"><i aria-hidden="true">${esc(s.symbol)}</i>${esc(s.short)}</button>`).join('')}</div>`;
const heading=(e,t,d,b='')=>`<div class="page-heading"><div><div class="eyebrow">${e}</div><h1>${t}</h1><p>${d}</p></div>${b}</div>`;
const questionCount=()=>LESSONS.reduce((a,l)=>a+l.questions.length,0);
const builtinLessons=()=>LESSONS.filter(l=>!l.custom);
const card=(l,i=0)=>`<a class="course-card theme-${i%4} subj-${l.subject}" href="#lesson/${l.id}"><div class="course-cover"><span class="cover-grade">${l.grade}-сынып</span>${l.custom?'<span class="cover-author">Мұғалім сабағы</span>':''}${window.BilimVisuals?window.BilimVisuals.cover(l,i):'<div class="cover-art">{ }</div>'}</div><div class="course-body"><div class="tag"><span class="subject-dot"></span>${esc(subjectOf(l.subject).short)} · ${esc(l.tag)}</div><h3>${esc(l.title)}</h3>${l.custom?`<div class="card-author">${esc(l.teacherName)}</div>`:''}<div class="course-bottom"><span>${l.minutes} минут · ${l.questions.length} сұрақ</span><span class="done-mark">${state.completed.includes(l.id)?'✓ Оқылды':''}</span><span class="round-arrow">↗</span></div></div></a>`;
let courseGrade=0,courseSubject=state.subject,olympGrade=0,olympSubject='all',examSubject=state.subject,query='',routeTimer=null,sortTimer=null,robotTimer=null,quiz=null,challengeId=null,challengeRevealed=false,challengeTries=0;
const examMinutes=(subject,n)=>subject==='informatics'?45:Math.max(10,Math.round(n*1.5));
function examPool(subject){return builtinLessons().filter(l=>l.subject===subject&&(subject!=='informatics'||l.grade>=8)).flatMap(l=>l.questions.map(q=>({...q,lesson:l.id,tag:l.tag})));}
let exam=null;try{const e=JSON.parse(sessionStorage.getItem(KEY+'-exam'));const n=e?.questions?.length;if(e&&n>=5&&n<=30&&e.questions.every(q=>typeof q.q==='string'&&typeof q.answer==='string'&&Array.isArray(q.options)&&q.options.length===4&&q.options.every(o=>typeof o==='string')&&typeof q.explain==='string')&&Array.isArray(e.answers)&&e.answers.length===n&&e.answers.every(a=>a===null||(Number.isInteger(a)&&a>=0&&a<=3))&&Number.isFinite(e.deadline)&&Number.isFinite(e.started)){e.pos=Math.max(0,Math.min(n-1,Number.isInteger(e.pos)?e.pos:0));e.subject=SUBJECTS.some(s=>s.id===e.subject)?e.subject:'informatics';exam=e;}}catch{}
function keepExam(){try{if(exam)sessionStorage.setItem(KEY+'-exam',JSON.stringify(exam));else sessionStorage.removeItem(KEY+'-exam');}catch{}}
function stats(){const xp=state.completed.length*20+state.solved.length*40+Object.values(state.quiz).reduce((a,b)=>a+b,0)*5+state.labs.length*25;return{xp,best:state.history.length?Math.round(Math.max(...state.history.map(x=>x.score/x.total))*100):0,level:1+Math.floor(xp/200)};}
function homeGrade(){const grades=gradesFor(state.subject);return grades.includes(state.grade)?state.grade:grades[0];}
function home(){const g=homeGrade(),s=subjectOf(state.subject);return `${heading('СЕНІҢ ЦИФРЛЫҚ КАМПУСЫҢ','Сәлем, болашақ жасаушы!','Бүгін жаңа нәрсе үйренуге тамаша күн.', `<span class="badge">5–11 сыныптар · ${SUBJECTS.length} пән</span>`)}
<section class="hero"><div><div class="eyebrow">БІЛІМНЕН — МҮМКІНДІККЕ</div><h1>Болашақтың<br>кодын <em>өзің жаз.</em></h1><p>Алғашқы алгоритмнен олимпиадаға дейін. Информатика, математика, физика және ҰБТ-ға дайындық — бір алаңда.</p><a class="btn lime" href="#courses">Оқуды бастау <span>↗</span></a><a class="btn text" href="#labs">Зерттеп көру →</a><div class="hero-tags"><span>Python</span><span>Математика</span><span>Физика</span><span>ҰБТ</span></div></div>${window.BilimVisuals?window.BilimVisuals.hero():''}</section>
<section class="stats"><div class="stat"><span class="stat-symbol">&lt;/&gt;</span><div><b>${LESSONS.length}</b><small>Түсінікті шағын сабақ</small></div></div><div class="stat"><span class="stat-symbol">☷</span><div><b>${questionCount()}</b><small>Түсіндірмелі сұрақ</small></div></div><div class="stat"><span class="stat-symbol">♜</span><div><b>${CHALLENGES.length}</b><small>Олимпиадалық есеп</small></div></div><div class="stat"><span class="stat-symbol">⚗</span><div><b>${LAB_IDS.length}</b><small>Интерактивті зертхана</small></div></div></section>
<section><div class="section-heading"><h2>Пәндер</h2><a href="#courses/all">Барлық сабақтар ↗</a></div><div class="subject-grid">${SUBJECTS.map(x=>{const list=LESSONS.filter(l=>l.subject===x.id),done=list.filter(l=>state.completed.includes(l.id)).length;return `<a class="subject-card s-${x.id}" href="#courses/${x.id}"><span class="subject-icon" aria-hidden="true">${esc(x.symbol)}</span><span class="subject-motto">${esc(x.motto)}</span><h3>${esc(x.name)}</h3><p>${esc(x.desc)}</p><div class="subject-meta"><span>${list.length} сабақ</span><span>${done} / ${list.length}</span></div><div class="progress-bar"><span style="width:${list.length?done/list.length*100:0}%"></span></div></a>`;}).join('')}</div></section>
<section class="home-columns"><div><div class="section-heading"><h2>Өз бағытыңды таңда</h2><a href="#courses/${s.id}">${esc(s.short)}: барлығы ↗</a></div>${subjectTabs(state.subject,'home')}${gradeTabs(g,'home',false,state.subject)}<div class="course-grid">${LESSONS.filter(l=>l.subject===state.subject&&l.grade===g).map(card).join('')||'<div class="empty">Бұл сыныпқа сабақ әлі жоқ.</div>'}</div></div><aside class="home-right"><div class="weekly"><span class="badge">БҮГІНГІ ЧЕЛЛЕНДЖ</span><h3>0 мен 1-дің<br>тілін түсінесің бе?</h3><p>Биттерді қосып, жасырылған санды тап. Компьютердің қалай ойлайтынын байқап көр.</p><a href="#lab/binary" class="btn">Сынап көремін <span>↗</span></a></div><div class="panel"><h3>Сенің оқу жолың</h3><ol class="journey-list"><li><span>01</span><div><p>Тақырыпты түсін</p><small>Қысқа теория мен мысал</small></div></li><li><span>02</span><div><p>Іс жүзінде байқап көр</p><small>Зертхана және есеп</small></div></li><li><span>03</span><div><p>Біліміңді тексер</p><small>Тест және кері байланыс</small></div></li></ol><div class="progress-bar"><span style="width:${state.completed.length/LESSONS.length*100}%"></span></div><small class="muted">${state.completed.length} / ${LESSONS.length} сабақ оқылды</small></div></aside></section>
<section class="topic-strip three"><a class="strip-card" href="#olympiad"><span class="strip-icon">♜</span><div><h3>Ойлау шекарасын кеңейт</h3><p>Олимпиадалық есептер · ${SUBJECTS.length} пән</p></div><span class="round-arrow">↗</span></a><a class="strip-card" href="#exam"><span class="strip-icon">✓</span><div><h3>ҰБТ-ға сенімді қадам</h3><p>Пән таңда · Таймер · Қателерді талдау</p></div><span class="round-arrow">↗</span></a><a class="strip-card teacher-strip" href="#teacher"><span class="strip-icon">✎</span><div><h3>Мұғалімсіз бе?</h3><p>Тіркеліп, сынып ашыңыз және сабақ жариялаңыз</p></div><span class="round-arrow">↗</span></a></section>`;}
function courseList(){return LESSONS.filter(l=>(courseSubject==='all'||l.subject===courseSubject)&&(!courseGrade||l.grade===courseGrade)&&`${l.title} ${l.tag} ${l.grade} ${subjectOf(l.subject).name} ${l.teacherName||''}`.toLowerCase().includes(query.toLowerCase()));}
function courses(){const s=courseSubject==='all'?null:subjectOf(courseSubject);if(courseGrade&&!gradesFor(courseSubject).includes(courseGrade))courseGrade=0;return `${heading(s?s.name.toUpperCase():'БАРЛЫҚ ПӘНДЕР','Білім кітапханасы',s?esc(s.desc)+' Әр сабақта түсіндірме, мысал және тест.':'Қысқа түсіндірме, шығарылған мысал және әр сабаққа тест.')}<section>${subjectTabs(courseSubject,'courses',true)}<div class="filters">${gradeTabs(courseGrade,'courses',true,courseSubject)}<input type="search" id="course-search" class="search-input" aria-label="Тақырыпты іздеу" placeholder="Тақырыпты іздеу…" value="${esc(query)}"></div><div class="question-summary" id="course-count"></div><div class="course-grid" id="course-results">${courseCards()}</div></section>`;}
function courseCards(){const list=courseList();return list.length?list.map(card).join(''):'<div class="empty">Тақырып табылмады. Басқа сөзбен іздеп көр.</div>';}
const practiceLink={informatics:['#labs','Зертханаға өту ↗','Тақырыпты көрнекі тәжірибемен бекіт.'],math:['#lab/graph','Функция зертханасы ↗','Түзудің еңісін өз қолыңмен өзгертіп көр.'],physics:['#lab/ohm','Ом заңы зертханасы ↗','Кернеу мен кедергіні өзгертіп, токты бақыла.'],mathlit:['#exam','ҰБТ тренингі ↗','Мат. сауаттылықтан тренинг тест тапсыр.']};
function lessonView(id){const l=LESSONS.find(x=>x.id===id);if(!l)return CUSTOM_ID.test(id)?'<section class="panel center"><div class="loader" aria-hidden="true"></div><p>Мұғалім сабағы жүктелуде…</p></section>':missing();const s=subjectOf(l.subject),p=practiceLink[l.subject];return `<a class="back" href="#courses/${l.subject}">← Сабақтарға қайту</a><section class="lesson-layout"><article class="panel lesson-content"><div class="lesson-meta"><span class="badge subject-badge s-${l.subject}">${esc(s.short)}</span><span class="badge green">${l.grade}-сынып</span><span class="badge">${esc(l.tag)}</span><span class="badge">${l.minutes} минут</span></div><h1>${esc(l.title)}</h1>${l.custom?`<div class="author-line"><span class="author-mini">${esc((l.teacherName||'М')[0])}</span><div><b>${esc(l.teacherName)}</b><small>${esc(l.teacherSchool||'')} · мұғалімнің авторлық сабағы</small></div></div>`:''}${l.paras.map(p=>`<p>${esc(p)}</p>`).join('')}${window.BilimVisuals?window.BilimVisuals.demo(l.id):''}${l.code?`<h2 class="space">Мысалмен түсін</h2><pre class="code-block">${esc(l.code)}</pre>`:''}${l.points.length?`<h2 class="space">Есте сақта</h2><ul class="key-points">${l.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}<div class="lesson-actions"><button class="btn lime" data-quiz="${l.id}">Білімімді тексеру <span>→</span></button><button class="btn secondary" data-complete="${l.id}">${state.completed.includes(l.id)?'✓ Оқылды':'Оқыдым деп белгілеу'}</button><button class="btn secondary" data-action="print">Басып шығару</button></div>${state.quiz[l.id]!==undefined?`<p class="lesson-score">Үздік нәтиже: ${state.quiz[l.id]} / ${l.questions.length}</p>`:''}</article><aside><div class="panel"><div class="eyebrow">${l.grade}-СЫНЫП · ${esc(s.short.toUpperCase())}</div><h3>Келесі қадамың</h3><div class="outline-links">${LESSONS.filter(x=>x.grade===l.grade&&x.subject===l.subject).map(x=>`<a href="#lesson/${x.id}" class="${x.id===id?'active':''}">${state.completed.includes(x.id)?'✓':'○'} ${esc(x.title)}</a>`).join('')}</div></div><div class="weekly"><h3>Теорияны іске қос</h3><p>${p[2]}</p><a class="btn" href="${p[0]}">${p[1]}</a></div></aside></section>`;}
function olympiad(){const list=CHALLENGES.map((c,i)=>({...c,i})).filter(c=>(olympSubject==='all'||c.subject===olympSubject)&&(!olympGrade||c.grade===olympGrade));return `${heading('ОЙЛА. БАЙҚАП КӨР. ШЕШ.','Олимпиада алаңы',`Заңдылықтардан динамикалық бағдарламалауға дейінгі ${CHALLENGES.length} есеп.`)}<section>${subjectTabs(olympSubject,'olympiad',true)}${gradeTabs(olympGrade,'olympiad',true)}<div class="notice">Жауап ретінде берілген нақты есептің нәтижесін енгіз. Көмек пен шешу жолы бар. Бұл бөлім толық бағдарламаларды іске қосып тексеретін жүйе емес.</div><div class="challenge-grid space">${list.map(c=>`<article class="panel challenge-card"><div class="lesson-meta"><span class="badge subject-badge s-${c.subject}">${esc(subjectOf(c.subject).short)}</span><span class="badge">${c.grade}-сынып</span><span class="badge ${c.level==='Күрделі'?'purple':'green'}">${state.solved.includes(c.i)?'✓ Шешілді':c.level}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.task)}</p><button class="btn secondary" data-challenge="${c.i}">Есепті ашу <span>↗</span></button></article>`).join('')||'<div class="empty">Бұл сүзгі бойынша есеп жоқ.</div>'}</div></section>`;}
function openChallenge(i){challengeId=i;challengeRevealed=false;challengeTries=0;const c=CHALLENGES[i];if(!c)return;openModal(`<div class="modal-top"><span class="badge green">${esc(subjectOf(c.subject).short)} · ${c.grade}-сынып · ${c.level}</span>${closeButton()}</div><h2 class="exercise-title">${esc(c.title)}</h2><p>${esc(c.task)}</p><div class="lab-code-label">БЕРІЛГЕНІ</div><pre class="code-block">${esc(c.input)}</pre><form id="challenge-form"><label for="challenge-answer">Сандық жауабың</label><div class="answer-row"><input required id="challenge-answer" inputmode="numeric" autocomplete="off" placeholder="Жауапты енгіз"><button class="btn" type="submit">Тексеру →</button></div></form><div id="challenge-feedback" aria-live="polite"></div><div class="row space"><button class="btn text" data-action="hint">Көмек керек пе?</button><button class="btn text" data-action="solution">Шешу жолын көру</button></div><div id="challenge-help" aria-live="polite"></div>`);}
function checkChallenge(){const c=CHALLENGES[challengeId],raw=$('#challenge-answer').value.trim().replace(/\s/g,''),correct=/^[+-]?\d+$/.test(raw)&&Number(raw)===Number(c.answer);challengeTries++;$('#challenge-feedback').innerHTML=`<div class="feedback ${correct?'correct':'wrong'}">${correct?'✓ Дұрыс жауап! '+esc(c.solution):'Әзірге сәйкес келмеді. Есеп шартын қайта оқып, тағы байқап көр.'}</div>`;if(correct&&!state.solved.includes(challengeId)&&!challengeRevealed){state.solved.push(challengeId);save();toast('+40 XP · Есеп шешілді!');}else if(correct&&challengeRevealed){$('#challenge-feedback').innerHTML+='<p class="notice">Шешімді көрдің. Бөлімді жауып, кейін өзің шығарып көрсең, жетістікке есептеледі.</p>';}}
const examInfo={informatics:'Python, логика, ақпарат көлемі, желілер және дерекқор',math:'Бөлшектер, теңдеулер, функция, геометрия, прогрессия, ықтималдық және туынды',physics:'Механика, жылу, электр, газ заңдары, толқындар және оптика',mathlit:'Пайыздар, мәтінді есептер, диаграммалар, статистика және логика'};
function examIntro(){const st=stats(),s=subjectOf(examSubject),n=Math.min(30,examPool(examSubject).length),best=state.history.filter(h=>h.subject===examSubject);return `${heading('ҰБТ ПӘНДЕРІ · ТРЕНИНГ','ҰБТ-ға дайындық','Пәнді таңда, уақытты бақыла және қате жауаптарыңды түсін.')}${subjectTabs(examSubject,'exam')}<section class="exam-intro"><div class="panel exam-card"><span class="badge green">АВТОРЛЫҚ ТРЕНИНГ · ${esc(s.name.toUpperCase())}</span><h2>Біліміңді<br>тәжірибеде сына.</h2><p>${esc(examInfo[examSubject])} тақырыптарынан ${n} сұрақ кездейсоқ таңдалады. Әр сұрақта бір дұрыс жауап бар. Соңында түсіндірмелер мен қайталауға арналған сабақтарды аласың.</p><div class="exam-specs"><div><b>${n}</b><small>сұрақ</small></div><div><b>${examMinutes(examSubject,n)}</b><small>минут</small></div><div><b>1</b><small>дұрыс жауап</small></div></div><button class="btn lime" data-action="exam-start">${exam?`Тестті жалғастыру (${esc(subjectOf(exam.subject).short)})`:'Тестті бастау'} →</button>${exam&&exam.subject!==examSubject?`<p class="notice space">Басталған ${esc(subjectOf(exam.subject).short)} тесті бар. Алдымен соны аяқта.</p>`:''}<p class="notice space">Бұл — авторлық дайындық тесті. Ресми ҰБТ нұсқасы емес; ресми емтиханның құрылымы мен бағалау жүйесін қайталамайды.</p></div><aside><div class="panel"><h3>Өзіңе ыңғайлы режим</h3><ul class="intro-steps"><li>Сұрақтар арасында еркін ауыс.</li><li>Жауапсыз сұрақтарға кейін орал.</li><li>Уақыт біткенде тест аяқталады.</li><li>Нәтижеден кейін қатені талда.</li></ul></div><div class="weekly"><span class="eyebrow">${esc(s.short.toUpperCase())}: ҮЗДІК НӘТИЖЕ</span><div class="result-score">${best.length?Math.round(Math.max(...best.map(h=>h.score/h.total))*100):0}<small>%</small></div><p>${best.length?`${best.length} аяқталған жаттығу · жалпы үздік ${st.best}%`:'Алғашқы нәтижені бүгін жаса.'}</p><a href="#courses/${examSubject}" class="btn secondary">Сабақтарды қайталау ↗</a></div></aside></section>`;}
function createExam(subject=examSubject){const pool=examPool(subject),n=Math.min(30,pool.length);exam={subject,questions:shuffle(pool).slice(0,n).map(q=>({...q,options:shuffle(q.options)})),answers:Array(n).fill(null),pos:0,started:Date.now(),deadline:Date.now()+examMinutes(subject,n)*60*1000};keepExam();}
function examView(){if(!exam)return examIntro();const n=exam.questions.length,q=exam.questions[exam.pos],done=exam.answers.filter(x=>x!==null).length;return `${heading(`${esc(subjectOf(exam.subject).name.toUpperCase())} · ТРЕНИНГ`,'Өз біліміңе сен.','Жауапты белгілеп, келесі сұраққа өт.')}<section class="exam-layout"><div class="panel exam-card"><div class="quiz-head"><span>Сұрақ ${exam.pos+1} / ${n}</span><span class="badge green">${esc(q.tag)}</span></div><div class="progress-bar"><span style="width:${done/n*100}%"></span></div><h2 class="quiz-question">${esc(q.q)}</h2><div class="quiz-options" role="group" aria-label="Жауап нұсқалары">${q.options.map((o,i)=>`<button class="option ${exam.answers[exam.pos]===i?'selected':''}" aria-pressed="${exam.answers[exam.pos]===i}" data-exam-answer="${i}"><span class="letter">${'ABCD'[i]}</span>${esc(o)}</button>`).join('')}</div><div class="quiz-footer"><button class="btn secondary" data-action="exam-prev" ${exam.pos===0?'disabled':''}>← Алдыңғы</button><button class="btn" data-action="exam-next" ${exam.pos===n-1?'disabled':''}>Келесі →</button></div></div><aside class="panel exam-nav"><div class="eyebrow">ҚАЛҒАН УАҚЫТ</div><div class="timer" id="exam-timer" aria-label="Қалған уақыт"></div><small class="muted">${done} / ${n} жауап берілді</small><div class="number-grid">${exam.questions.map((q,i)=>`<button data-exam-pos="${i}" aria-label="${i+1}-сұрақ${exam.answers[i]!==null?', жауап берілді':''}" class="${exam.answers[i]!==null?'answered':''} ${i===exam.pos?'current':''}" ${i===exam.pos?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><button class="btn" data-action="exam-finish">Тестті аяқтау ✓</button><p class="notice space">Таңдауың осы қойындыда сақталады. Жауаптарды аяқтаған соң талдай аласың.</p></aside></section>`;}
function updateTimer(){if(!exam||!$('#exam-timer'))return;const left=Math.max(0,Math.ceil((exam.deadline-Date.now())/1000));$('#exam-timer').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;$('#exam-timer').classList.toggle('urgent',left<300);if(!left)finishExam(true);}
let lastResult=null;
function finishExam(auto=false){if(!exam)return;if(!auto){const unanswered=exam.answers.filter(x=>x===null).length;openModal(`<div class="modal-top"><h2>Тестті аяқтаймыз ба?</h2>${closeButton()}</div><p>${unanswered?`${unanswered} сұрақ әлі жауапсыз. Олар 0 балл болып есептеледі.`:'Барлық сұраққа жауап бердің.'}</p><div class="row"><button class="btn" data-action="exam-confirm">Аяқтап, нәтижені көру</button><button class="btn secondary" data-action="modal-close">Тестке оралу</button></div>`);return;}commitExam();}
function commitExam(){if(!exam)return;clearInterval(routeTimer);const n=exam.questions.length,correct=exam.questions.filter((q,i)=>q.options[exam.answers[i]]===q.answer).length;lastResult={...exam,score:correct};state.history.unshift({score:correct,total:n,subject:exam.subject,date:Date.now(),time:Math.min(5400,Math.max(0,Math.round((Date.now()-exam.started)/1000)))});state.history=state.history.slice(0,30);save();exam=null;keepExam();if($('#modal').open)$('#modal').close();if(location.hash==='#result')render();else location.hash='#result';if(correct/n>=.6&&window.BilimMotion)window.BilimMotion.celebrate('exam');}
function resultView(){if(!lastResult)return `${heading('ТЕСТ НӘТИЖЕСІ','Нәтиже жетістіктерде сақталды','Толық сұрақ талдауы тест аяқталған қойындыда ғана қолжетімді.')}<a class="btn" href="#progress">Жетістіктерім →</a>`;const r=lastResult,n=r.questions.length,wrong=r.questions.filter((q,i)=>q.options[r.answers[i]]!==q.answer),recommended=[...new Set(wrong.map(q=>q.lesson))];return `${heading('ӨЗІҢМЕН ӨЗІҢ ЖАРЫС','Тағы бір қадам алға!','Нәтижең сақталды. Енді әр қатені жаңа білімге айналдыр.')}<section><div class="panel center"><div class="eyebrow">${esc(subjectOf(r.subject).name.toUpperCase())} · ТЕСТ НӘТИЖЕСІ</div><div class="result-score">${r.score}<small> / ${n}</small></div><p>${Math.round(r.score/n*100)}% дұрыс · ${wrong.length} сұрақты қайталау керек</p><div class="row" style="justify-content:center"><button class="btn lime" data-action="exam-retry">Жаңа тест →</button><a class="btn secondary" href="#progress">Жетістіктерім</a></div></div>${recommended.length?`<div class="panel"><h3>Қайталауға ұсынылатын сабақтар</h3><div class="row">${recommended.map(id=>{const l=LESSONS.find(l=>l.id===id);return l?`<a class="badge green" href="#lesson/${l.id}">${esc(l.title)} ↗</a>`:'';}).join('')}</div></div>`:''}<div class="section-heading"><h2>Жауаптарды талдау</h2><span class="badge">${n} түсіндірме</span></div>${r.questions.map((q,i)=>{const chosen=q.options[r.answers[i]];return `<article class="review-item ${chosen===q.answer?'ok':'miss'}"><h4>${chosen===q.answer?'✓':'○'} ${i+1}. ${esc(q.q)}</h4><p>Сенің жауабың: ${chosen?esc(chosen):'Жауап берілмеді'}</p><p class="correct-text">Дұрыс жауап: ${esc(q.answer)}</p><p>${esc(q.explain)}</p></article>`;}).join('')}</section>`;}
const LABS=[['binary','01 10','Екілік код шебері','8 битті қосып-өшір. Ондық санды екілікке айналдыруды қолмен байқап көр.','informatics'],['sorting','bars','Тірі сұрыптау','Көрші элементтер қалай салыстырылады? Алгоритмді қадамдап жүргіз.','informatics'],['pixels','▦','Пиксель суретшісі','8×8 суретті 0 мен 1 арқылы сал. Жолдардың екілік және HEX кодын көр.','informatics'],['robot','↑ → ↓','Роботқа жол көрсет','Командалар тізбегін құрастыр. Қабырғаларды айналып, мақсатқа жет.','informatics'],['graph','y=kx+b','Функция графигі','k мен b-ны жылжытып, түзуді берілген нүктелер арқылы өткіз.','math'],['ohm','I=U/R','Ом заңы','Кернеу мен кедергіні өзгертіп, шамды қажетті токпен жандыр.','physics']];
function labHome(){return `${heading('БІЛІМДІ ҚОЛМЕН СЕЗІН','Интерактивті зертханалар','Өзгерткен сайын нәтижені көр. Түсінудің ең жақсы жолы — тәжірибе.')}<section class="lab-grid">${LABS.map(([id,symbol,t,d,subj])=>`<a class="lab-card" href="#lab/${id}"><div class="lab-visual ${symbol.length>6?'formula':''}">${symbol==='bars'?'<div class="mini-bars"><i style="height:30px"></i><i style="height:55px"></i><i style="height:22px"></i><i style="height:65px"></i><i style="height:42px"></i></div>':esc(symbol)}</div><span class="badge subject-badge s-${subj}">${esc(subjectOf(subj).short)}</span><h3>${t}</h3><p>${d}</p><div class="row"><span class="badge green">${state.labs.includes(id)?'✓ Зерттелді':'Тәжірибені баста'}</span><span class="round-arrow">↗</span></div></a>`).join('')}</section>`;}
let bits=Array(8).fill(0),binaryTarget=null,binaryWon=false,sortFrames=[],sortIndex=0,pixels=Array(64).fill(0),robotCommands=[],robotPosition=[0,5],robotRunning=false;
let graph={k:1,b:0,target:null,won:false},ohm={u:12,r:6,target:null,won:false};
const WALLS=[[1,4],[2,4],[3,2],[4,2]];
function labAward(id){if(!state.labs.includes(id)){state.labs.push(id);save();toast('+25 XP · Зертхана ашылды!');}}
function binaryView(){const value=parseInt(bits.join(''),2);return `<div class="lab-stage"><div class="eyebrow center">${binaryTarget===null?'БИТТЕРДІ ТҮРТІП КӨР':`МИССИЯ: ${binaryTarget} САНЫН ҚҰРАСТЫР`}</div><div class="bit-row">${bits.map((b,i)=>`<button class="bit-btn ${b?'on':''}" data-bit="${i}" aria-label="${2**(7-i)} разряды, ${b}" aria-pressed="${!!b}"><small>${2**(7-i)}</small><b>${b}</b></button>`).join('')}</div><div class="binary-value">${value}<small>ондық сан</small></div><p class="lab-note">${bits.map((b,i)=>b?2**(7-i):0).filter(x=>x).join(' + ')||'0'} = ${value}</p><div class="control-row"><button class="btn lime" data-action="binary-mission">${binaryTarget===null?'Миссияны бастау':'Жаңа миссия'} ↗</button><button class="btn secondary" data-action="binary-reset">Нөлге түсіру</button></div><div id="binary-feedback" role="status" class="center">${binaryWon?'<div class="feedback correct">✓ Керемет! Барлық разрядты дұрыс қостың.</div>':''}</div></div><aside class="panel"><h3>Компьютердің әліпбиі</h3><p>Әр батырма — бір бит. Жоғарыдағы сан оның салмағын көрсетеді. 1 тұрған биттердің салмақтары қосылады.</p><pre class="code-block">00000101₂\n= 4 + 1\n= 5₁₀</pre><p>8 бит → 1 байт → 256 түрлі мән. Барлық бит қосылса, ең үлкен сан — 255.</p><a class="btn text" href="#lesson/binary">Сабақты оқу →</a></aside>`;}
function makeSort(){const a=shuffle([9,18,27,36,45,54,63,72]);sortFrames=[{a:[...a],pair:[],text:'Алдымен көрші екі элементті салыстырамыз.'}];for(let i=0;i<a.length-1;i++){let changed=false;for(let j=0;j<a.length-1-i;j++){sortFrames.push({a:[...a],pair:[j,j+1],text:`${a[j]} және ${a[j+1]} салыстырылады.`});if(a[j]>a[j+1]){const before=`${a[j]} > ${a[j+1]}`;[a[j],a[j+1]]=[a[j+1],a[j]];changed=true;sortFrames.push({a:[...a],pair:[j,j+1],text:`${before}: орындары ауысты.`});}}if(!changed)break;}sortFrames.push({a:[...a],pair:[],text:'Дайын! Барлық элемент өсу ретімен орналасты.',done:true});sortIndex=0;}
function sortingView(){if(!sortFrames.length)makeSort();const f=sortFrames[sortIndex];return `<div class="lab-stage"><div class="quiz-head"><span>Көпіршікті сұрыптау</span><span>${sortIndex+1} / ${sortFrames.length} қадам</span></div><div class="sort-stage">${f.a.map((n,i)=>`<div class="sort-bar ${f.done?'done':f.pair.includes(i)?'compare':''}" style="height:${n/72*90}%"><span>${n}</span></div>`).join('')}</div><p class="lab-note" aria-live="polite">${f.text}</p><div class="control-row"><button class="btn secondary" data-action="sort-prev" ${sortIndex===0?'disabled':''} aria-label="Алдыңғы қадам">←</button><button class="btn lime" data-action="sort-play" ${f.done?'disabled':''}>${sortTimer?'Ⅱ Тоқтату':'▶ Жүргізу'}</button><button class="btn secondary" data-action="sort-next" ${f.done?'disabled':''}>Бір қадам →</button><button class="btn secondary" data-action="sort-reset">↻ Жаңарту</button></div></div><aside class="panel"><h3>Реттілік қалай туады?</h3><p>Алгоритм көрші элементтерді салыстырады. Сол жақтағысы үлкен болса, екеуін ауыстырады. Әр өтуден кейін ең үлкен қалған элемент оң жаққа жылжиды.</p><p><b>Сары түс</b> — салыстырылып жатқан жұп. <b>Жасыл түс</b> — сұрыптау аяқталды.</p><pre class="code-block">if a[j] > a[j+1]:\n    a[j], a[j+1] = \\\n        a[j+1], a[j]</pre><a class="btn text" href="#lesson/sorting">Сабақты оқу →</a></aside>`;}
function sortNext(){if(sortIndex<sortFrames.length-1){sortIndex++;if(sortFrames[sortIndex].done){clearInterval(sortTimer);sortTimer=null;labAward('sorting');}refreshLab();}}
function pixelsView(){return `<div class="lab-stage"><div class="eyebrow center">1 БИТТІК ГРАФИКА · 8 × 8</div><div class="pixel-grid" role="group" aria-label="8 қатар, 8 баған пиксель суреті">${pixels.map((p,i)=>`<button class="pixel ${p?'on':''}" data-pixel="${i}" aria-label="${Math.floor(i/8)+1}-қатар, ${i%8+1}-баған" aria-pressed="${!!p}"></button>`).join('')}</div><p class="lab-note">${pixels.reduce((a,b)=>a+b,0)} пиксель боялған · 64 бит = 8 байт шикі дерек</p><div class="control-row"><button class="btn lime" data-action="pixel-example">Жүрек сал ♡</button><button class="btn secondary" data-action="pixel-clear">Тазалау</button><button class="btn secondary" data-action="pixel-download">SVG жүктеу ↓</button></div></div><aside class="panel"><h3>Суреттің коды</h3><p>Боялған ұяшық — 1, бос ұяшық — 0. Әр қатар бір байт болады. HEX бағаны сол байттың он алтылық жазылуын көрсетеді.</p><div class="lab-code-label">ЕКІЛІК КОД → HEX</div><pre class="pixel-code">${Array.from({length:8},(_,i)=>{const row=pixels.slice(i*8,i*8+8).join('');return `${row}  →  ${parseInt(row,2).toString(16).toUpperCase().padStart(2,'0')}`;}).join('\n')}</pre><p class="notice">8 байт — тек пиксель мәндерінің көлемі. Жүктелетін SVG файлының толық көлеміне мәтін мен тегтер де кіреді.</p></aside>`;}
function robotView(){return `<div class="lab-stage"><div class="eyebrow center">КОМАНДАЛАРДЫ ДҰРЫС РЕТПЕН ОРНАЛАСТЫР</div><div class="robot-grid" aria-label="Робот картасы">${Array.from({length:36},(_,i)=>{const x=i%6,y=Math.floor(i/6),wall=WALLS.some(p=>p[0]===x&&p[1]===y),bot=robotPosition[0]===x&&robotPosition[1]===y,goal=x===5&&y===0;return `<div data-cell="${i}" class="robot-cell ${wall?'wall':''} ${goal?'goal':''} ${bot?'robot':''}" aria-label="${x+1}-баған, ${y+1}-қатар: ${bot?'робот':wall?'қабырға':goal?'мақсат':'бос'}">${bot?'▣':wall?'▪':goal?'⚑':''}</div>`;}).join('')}</div><div class="robot-caption"><span>▣ Робот</span><span>▪ Қабырға</span><span>⚑ Мақсат</span></div><div id="robot-feedback" aria-live="polite" class="center"></div></div><aside class="panel"><h3>Сен — бағдарламашысың</h3><p>Робот төменгі сол жақтан бастайды. Жоғарғы оң жақтағы жалауға жеткіз. Әр команда картадағы бағытпен 1 ұяшық жылжытады.</p><div class="command-buttons">${[['up','↑'],['right','→'],['down','↓'],['left','←']].map(([id,s])=>`<button data-command="${id}" aria-label="${{up:'Жоғары',right:'Оңға',down:'Төмен',left:'Солға'}[id]}" ${robotRunning?'disabled':''}>${s}</button>`).join('')}</div><div class="program-list" aria-label="Командалар тізімі">${robotCommands.map(c=>({up:'↑',right:'→',down:'↓',left:'←'}[c])).join(' ')||'<small class="muted">Командаларды осы жерге жина…</small>'}</div><small class="muted">${robotCommands.length} / 30 команда</small><div class="row space"><button class="btn lime" data-action="robot-run" ${robotRunning||!robotCommands.length?'disabled':''}>▶ Іске қосу</button><button class="btn secondary small" data-action="robot-undo" ${robotRunning||!robotCommands.length?'disabled':''}>← Өшіру</button><button class="btn secondary small" data-action="robot-clear" ${robotRunning?'disabled':''}>↻ Тазалау</button></div></aside>`;}
const signed=n=>n<0?`− ${Math.abs(n)}`:`+ ${n}`;
const lineText=(k,b)=>`y = ${k===0?'':k===1?'x':k===-1?'−x':(k<0?'−':'')+Math.abs(k)+'x'}${k===0?b:b?' '+signed(b):''}`.replace(/= $/,'= 0');
function graphPoints(){if(!graph.target)return [];const {k,b,xa,xb}=graph.target;return [[xa,k*xa+b,'A'],[xb,k*xb+b,'B']];}
function graphSvg(){const S=20,C=140,X=x=>C+x*S,Y=y=>C-y*S,lines=[];for(let i=-6;i<=6;i++)lines.push(`<path d="M${X(i)} 10V270M10 ${Y(i)}H270" class="${i===0?'axis':'grid'}"/>`);const y1=graph.k*-7+graph.b,y2=graph.k*7+graph.b;return `<svg class="graph-svg" viewBox="0 0 280 280" role="img" aria-label="Координаталық жазықтықтағы ${esc(lineText(graph.k,graph.b))} түзуі"><defs><clipPath id="plot-clip"><rect x="10" y="10" width="260" height="260" rx="10"/></clipPath></defs><rect x="10" y="10" width="260" height="260" rx="10" class="plot-bg"/>${lines.join('')}<text x="262" y="${Y(0)-6}" class="axis-label">x</text><text x="${X(0)+6}" y="22" class="axis-label">y</text><g clip-path="url(#plot-clip)"><line x1="${X(-7)}" y1="${Y(y1)}" x2="${X(7)}" y2="${Y(y2)}" class="plot-line ${graph.won?'won':''}"/></g>${graphPoints().map(([x,y,n])=>`<circle cx="${X(x)}" cy="${Y(y)}" r="6" class="target-point"/><text x="${X(x)+9}" y="${Y(y)-8}" class="point-label">${n}(${x}; ${y})</text>`).join('')}${Math.abs(graph.b)<=6?`<circle cx="${X(0)}" cy="${Y(graph.b)}" r="4.5" class="intercept"/>`:''}</svg>`;}
function graphView(){const pts=graphPoints();return `<div class="lab-stage"><div class="eyebrow center" id="graph-mission">${graph.target?`МИССИЯ: ТҮЗУ ${pts.map(p=>`${p[2]}(${p[0]}; ${p[1]})`).join(' ЖӘНЕ ')} АРҚЫЛЫ ӨТСІН`:'k МЕН b-НЫ ӨЗГЕРТІП КӨР'}</div><div class="graph-wrap" id="graph-plot">${graphSvg()}</div><div class="binary-value formula-value" id="graph-formula">${esc(lineText(graph.k,graph.b))}<small>${graph.k>0?'функция өседі':graph.k<0?'функция кемиді':'тұрақты функция'}</small></div><div class="control-row"><button class="btn lime" data-action="graph-mission">${graph.target?'Жаңа миссия':'Миссияны бастау'} ↗</button><button class="btn secondary" data-action="graph-reset">↻ Бастапқы күй</button></div><div id="graph-feedback" role="status" class="center">${graph.won?'<div class="feedback correct">✓ Тамаша! Түзу екі нүкте арқылы өтті.</div>':''}</div></div><aside class="panel"><h3>Түзуді басқар</h3><label class="range-field"><span>Бұрыштық коэффициент <b>k = <output id="k-out">${graph.k}</output></b></span><input type="range" min="-5" max="5" step="1" value="${graph.k}" data-range="k" aria-label="k коэффициенті"></label><label class="range-field"><span>Бос мүше <b>b = <output id="b-out">${graph.b}</output></b></span><input type="range" min="-6" max="6" step="1" value="${graph.b}" data-range="b" aria-label="b бос мүшесі"></label><p><b>k</b> түзудің еңісін береді: x бір бірлікке артқанда y қаншаға өзгереді. <b>b</b> — түзудің Oy осін қиятын нүктесі (лайм түсті нүкте).</p><p class="notice">Кеңес: алдымен b-ны таңда, сосын екі нүкте арасындағы өсімді x-тің өсіміне бөліп, k-ны тап.</p><a class="btn text" href="#lesson/m-function">Сабақты оқу →</a></aside>`;}
function updateGraph(){if(!$('#graph-plot'))return;$('#graph-plot').innerHTML=graphSvg();$('#graph-formula').innerHTML=`${esc(lineText(graph.k,graph.b))}<small>${graph.k>0?'функция өседі':graph.k<0?'функция кемиді':'тұрақты функция'}</small>`;$('#k-out').textContent=graph.k;$('#b-out').textContent=graph.b;$('#graph-feedback').innerHTML=graph.won?'<div class="feedback correct">✓ Тамаша! Түзу екі нүкте арқылы өтті.</div>':'';}
function graphMission(){let t;do{const k=shuffle([-3,-2,-1,1,2,3])[0],b=Math.floor(Math.random()*9)-4,xa=-1-Math.floor(Math.random()*2),xb=1+Math.floor(Math.random()*2);t={k,b,xa,xb};}while([t.xa,t.xb].some(x=>Math.abs(t.k*x+t.b)>6)||(t.k===graph.k&&t.b===graph.b));graph.target=t;graph.won=false;}
const amps=x=>Number.isInteger(x)?String(x):x.toFixed(2).replace(/0$/,'').replace('.',',');
function ohmState(){const i=ohm.u/ohm.r,p=ohm.u*i;return {i,p,glow:Math.min(1,p/60),speed:i>0?Math.max(.35,3/i):0};}
function ohmSvg(){const {i,glow,speed}=ohmState();return `<svg class="circuit-svg" viewBox="0 0 320 210" role="img" aria-label="Батарея, резистор және шамнан тұратын тізбек, ток күші ${amps(i)} ампер"><rect x="40" y="35" width="240" height="140" rx="18" class="wire"/><rect x="40" y="35" width="240" height="140" rx="18" class="current ${i?'':'still'}" style="--flow:${speed.toFixed(2)}s"/><g class="battery"><rect x="22" y="80" width="36" height="50" rx="7"/><path d="M33 96h14M40 89v14M33 116h14"/></g><text x="66" y="110" class="circuit-label">${ohm.u} В</text><g class="resistor"><rect x="125" y="23" width="70" height="24" rx="7"/><path d="M135 35l6-7 8 14 8-14 8 14 8-14 6 7"/></g><text x="160" y="72" class="circuit-label center">${ohm.r} Ом</text><circle cx="280" cy="105" r="${26+glow*20}" class="bulb-glow" style="opacity:${(.15+glow*.8).toFixed(2)}"/><g class="bulb" style="--glow:${glow.toFixed(2)}"><circle cx="280" cy="105" r="18"/><path d="M273 106c2-6 5-6 7 0s5 6 7 0"/></g><text x="160" y="160" class="circuit-label center strong">I = ${amps(i)} А</text></svg>`;}
function ohmReadout(){const {i,p}=ohmState();return `<div><small>Кернеу</small><b>${ohm.u} В</b></div><div><small>Кедергі</small><b>${ohm.r} Ом</b></div><div class="hl"><small>Ток күші</small><b>${amps(i)} А</b></div><div><small>Қуат</small><b>${amps(Math.round(p*100)/100)} Вт</b></div>`;}
function ohmView(){return `<div class="lab-stage"><div class="eyebrow center" id="ohm-mission">${ohm.target?`МИССИЯ: ТОК КҮШІН ДӘЛ ${amps(ohm.target)} А ЕТ`:'КЕРНЕУ МЕН КЕДЕРГІНІ ӨЗГЕРТ'}</div><div class="circuit-wrap" id="ohm-plot">${ohmSvg()}</div><div class="ohm-readout" id="ohm-readout">${ohmReadout()}</div><div class="control-row"><button class="btn lime" data-action="ohm-mission">${ohm.target?'Жаңа миссия':'Миссияны бастау'} ↗</button><button class="btn secondary" data-action="ohm-reset">↻ Бастапқы күй</button></div><div id="ohm-feedback" role="status" class="center">${ohm.won?'<div class="feedback correct">✓ Дәл таптың! Ом заңы жұмыс істейді.</div>':''}</div></div><aside class="panel"><h3>Тізбекті басқар</h3><label class="range-field"><span>Кернеу <b>U = <output id="u-out">${ohm.u}</output> В</b></span><input type="range" min="0" max="24" step="1" value="${ohm.u}" data-range="u" aria-label="Кернеу, вольт"></label><label class="range-field"><span>Кедергі <b>R = <output id="r-out">${ohm.r}</output> Ом</b></span><input type="range" min="1" max="20" step="1" value="${ohm.r}" data-range="r" aria-label="Кедергі, ом"></label><pre class="code-block">I = U / R\nP = U · I</pre><p>Кернеуді арттырсаң, ток өседі. Кедергіні арттырсаң, ток азаяды. Шамның жарықтығы қуатқа байланысты.</p><a class="btn text" href="#lesson/p-ohm">Сабақты оқу →</a></aside>`;}
function updateOhm(){if(!$('#ohm-plot'))return;$('#ohm-plot').innerHTML=ohmSvg();$('#ohm-readout').innerHTML=ohmReadout();$('#u-out').textContent=ohm.u;$('#r-out').textContent=ohm.r;$('#ohm-feedback').innerHTML=ohm.won?'<div class="feedback correct">✓ Дәл таптың! Ом заңы жұмыс істейді.</div>':'';}
function ohmMission(){const options=[.5,1,1.5,2,2.5,3,4,5,6].filter(x=>Math.abs(ohm.u/ohm.r-x)>1e-9);ohm.target=shuffle(options)[0];ohm.won=false;}
function labView(id){const lab=LABS.find(l=>l[0]===id);if(!lab)return missing();return `<a class="back" href="#labs">← Зертханаларға қайту</a>${heading('ЦИФРЛЫҚ ТӘЖІРИБЕ',lab[2],'Әр әрекет — түсінуге тағы бір қадам.')}<section class="lab-layout" id="lab-content">${labViews[id]()}</section>`;}
const labViews={binary:binaryView,sorting:sortingView,pixels:pixelsView,robot:robotView,graph:graphView,ohm:ohmView};
function refreshLab(){const id=location.hash.split('/')[1];const fn=labViews[id];if(fn&&$('#lab-content')){$('#lab-content').innerHTML=fn();if(window.BilimMotion)window.BilimMotion.labFrame(id);}}
function runRobot(){if(robotRunning||!robotCommands.length)return;robotRunning=true;robotPosition=[0,5];refreshLab();let i=0;robotTimer=setInterval(()=>{if(i>=robotCommands.length){stopRobot();return;}const c=robotCommands[i++],d={up:[0,-1],right:[1,0],down:[0,1],left:[-1,0]}[c],next=[robotPosition[0]+d[0],robotPosition[1]+d[1]];if(next.some(n=>n<0||n>5)||WALLS.some(p=>p[0]===next[0]&&p[1]===next[1])){stopRobot(`${i}-қадамда кедергіге тірелді. Командалар ретін өзгерт.`);return;}robotPosition=next;refreshLab();if(next[0]===5&&next[1]===0){stopRobot('✓ Мақсатқа жеттің! Алгоритмің дұрыс.');labAward('robot');}else if(i===robotCommands.length)stopRobot('Командалар бітті. Мақсатқа жету үшін жолды толықтыр.');},420);}
function stopRobot(message='Командалар бітті. Жолды толықтыр.'){clearInterval(robotTimer);robotTimer=null;robotRunning=false;refreshLab();if($('#robot-feedback'))$('#robot-feedback').innerHTML=`<div class="feedback ${robotPosition[0]===5&&robotPosition[1]===0?'correct':''}">${esc(message)}</div>`;}
function classCard(){const a=window.BilimAPI?.auth();if(a?.role==='student'&&a.class){const sync=window.BilimAPI.lastSync;return `<div class="panel class-card joined"><span class="badge green">СЕН СЫНЫПТАСЫҢ</span><h3>${esc(a.class.name)} · ${esc(subjectOf(a.class.subject).short)}</h3><p>Мұғалімің: <b>${esc(a.class.teacher)}</b>. Прогресің мұғалімге автоматты түрде жіберіледі.${window.BilimAPI.mode==='local'?' Жергілікті режимде мұғалім деректерді тек осы құрылғыдан көреді.':''}</p><div class="row"><span class="badge">${sync?'Соңғы жіберілгені: '+new Date(sync).toLocaleTimeString('kk-KZ',{hour:'2-digit',minute:'2-digit'}):'Синхрондау қосулы'}</span><button class="btn secondary small" data-action="sync-now">Қазір жіберу ↑</button><button class="btn danger small" data-action="leave-class">Сыныптан шығу</button></div></div>`;}return `<div class="panel class-card"><span class="badge purple">СЫНЫПҚА ҚОСЫЛ</span><h3>Мұғаліміңнің коды бар ма?</h3><p>6 таңбалы кодты енгізсең, мұғалімің сенің сабақтарың мен тест нәтижелеріңді көреді және саған арнайы сабақтар ашады.</p><a class="btn" href="#join">Кодты енгізу <span>↗</span></a></div>`;}
function progress(){const s=stats(),earnedSubjects=id=>LESSONS.filter(l=>l.subject===id&&state.completed.includes(l.id)).length;const badges=[['◇','Алғашқы қадам','Бір сабақ оқы',state.completed.length>0],['⌘','Код зерттеушісі','Информатикадан 6 сабақ оқы',earnedSubjects('informatics')>=6],['∑','Жас математик','Математикадан 3 сабақ оқы',earnedSubjects('math')>=3],['⚛','Жас физик','Физикадан 3 сабақ оқы',earnedSubjects('physics')>=3],['%','Сауатты есепші','Мат. сауаттылықтан 3 сабақ оқы',earnedSubjects('mathlit')>=3],['♜','Есеп шебері','3 олимпиада есебін шеш',state.solved.length>=3],['⚗','Тәжірибе көшбасшысы',`${LAB_IDS.length} зертхананы зертте`,state.labs.length===LAB_IDS.length],['★','ҰБТ батыры','Кез келген тренингтен 80%+',state.history.some(h=>h.score/h.total>=.8)]];return `${heading('КЕШЕГІ ӨЗІҢНЕН БІР ҚАДАМ АЛҒА','Менің жетістігім','Бұл құрылғыдағы оқу жолың мен нәтижелерің.')}<section><div class="progress-top"><div class="panel"><span class="badge green">${s.level}-ДЕҢГЕЙ · ЖАС ЗЕРТТЕУШІ</span><div class="score-row"><div class="result-score">${s.xp}<small> XP</small></div><div class="progress-orb" style="--progress:${s.xp%200/2}%" aria-label="${s.level}-деңгей"><span>${s.level}<small>ДЕҢГЕЙ</small></span></div></div><div class="progress-bar"><span style="width:${s.xp%200/2}%"></span></div><p>Келесі деңгейге ${200-s.xp%200} XP қалды.</p><small class="muted">Оқылған сабақ: +20 · Тесттегі әр жаңа дұрыс жауап: +5<br>Шешілген есеп: +40 · Зертхана: +25</small></div><div class="panel"><h3>Жинаған тәжірибең</h3><div class="history-row"><span>Оқылған сабақ</span><b>${state.completed.length} / ${LESSONS.length}</b></div><div class="history-row"><span>Шешілген есеп</span><b>${state.solved.length} / ${CHALLENGES.length}</b></div><div class="history-row"><span>Зерттелген зертхана</span><b>${state.labs.length} / ${LAB_IDS.length}</b></div><div class="history-row"><span>ҰБТ тренингіндегі үздік нәтиже</span><b>${s.best}%</b></div></div></div>${classCard()}<div class="section-heading"><h2>Белгілерің</h2><span class="badge">Еңбегің — өзіңе сый</span></div><div class="achievement-grid">${badges.map(([symbol,t,d,earned])=>`<div class="achievement ${earned?'earned':''}"><span class="medal">${symbol}</span><b>${t} ${earned?'✓':''}</b><small>${d}</small></div>`).join('')}</div><div class="section-heading space"><h2>Пәндер бойынша</h2></div><div class="grade-progress subject-progress">${SUBJECTS.map(x=>{const total=LESSONS.filter(l=>l.subject===x.id).length,count=earnedSubjects(x.id);return `<a class="panel s-${x.id}" href="#courses/${x.id}"><strong>${esc(x.symbol)}</strong><small class="muted">${esc(x.short)}</small><div class="progress-bar"><span style="width:${total?count/total*100:0}%"></span></div><span>${count} / ${total} сабақ</span></a>`;}).join('')}</div><div class="panel"><h3>Тест тарихы</h3>${state.history.length?state.history.map(h=>`<div class="history-row"><span>${new Date(h.date).toLocaleDateString('kk-KZ')} · ${esc(subjectOf(h.subject).short)} · ${Math.floor(h.time/60)} мин ${h.time%60} сек</span><b>${h.score} / ${h.total} · ${Math.round(h.score/h.total*100)}%</b></div>`).join(''):'<p>Әзірге аяқталған тест жоқ. Алғашқы тестіңді орындап көр.</p><a class="btn secondary" href="#exam">Тестке өту →</a>'}</div><div class="panel"><h3>Прогресті өзіңмен бірге ал</h3><p>Нәтижелер осы браузерде сақталады. Басқа құрылғыға көшіру үшін JSON файлын жүктеп алып, сол құрылғыда импортта. Браузер деректерін тазалау прогресті өшіруі мүмкін.</p><div class="row"><button class="btn secondary" data-action="export">JSON жүктеу ↓</button><button class="btn secondary" data-action="import">Прогресті импорттау ↑</button><button class="btn danger" data-action="reset">Тазалау</button><input type="file" id="import-file" accept="application/json,.json" hidden></div></div></section>`;}
function about(){return `<section class="about-hero"><div class="eyebrow" style="color:var(--lime)">БУРЫЛ АУЫЛЫ · №6 ОРТА МЕКТЕП</div><h1>Білім PRO</h1><p>Оқушының цифрлық сауаттылығын, алгоритмдік ойлауын және өздігінен білім алу дағдысын дамытуға арналған мектептің оқу жобасы. Информатикадан басталған алаң енді математика, физика және математикалық сауаттылықты қамтиды, ал кез келген мұғалім тіркеліп, өз сабағын жариялай алады.</p><span class="badge" style="color:#c6d9ce;border-color:#ffffff33">5–11 сынып · ${SUBJECTS.map(s=>s.short).join(' · ')}</span></section><section class="author-grid"><article class="author-card"><div class="author-avatar">М</div><div class="eyebrow">ЖОБА ЖЕТЕКШІСІ</div><h3>Инкарбекова<br>Маржан Асилхановна</h3><p>Информатика пәнінің мұғалімі<br>Бурыл ауылы, №6 орта мектеп</p></article><article class="author-card"><div class="author-avatar" style="background:var(--purple);color:#8b6eaa">І</div><div class="eyebrow">ЖОБА АВТОРЫ · ОҚУШЫ</div><h3>Амангелді<br>Іңкәр</h3><p>Білім PRO оқу жобасы</p></article><article class="author-card"><div class="author-avatar" style="background:var(--orange);color:#9e7d48">Н</div><div class="eyebrow">ЖОБА АВТОРЫ · ОҚУШЫ</div><h3>Кубеева<br>Нұрай</h3><p>Білім PRO оқу жобасы</p></article></section><section class="topic-strip"><div class="panel"><h3>Неге бұл жоба қажет?</h3><p>Теорияны жаттап қана қоймай, тәжірибеде түсінуге көмектесу. Бір алаңда сабақ оқып, есеп шығарып, лабораторияда байқап, өз нәтижесін бақылауға мүмкіндік беру. Мұғалімдер сынып ашып, оқушылардың прогресін бір жерден көре алады.</p><div class="info-list"><span><b>${builtinLessons().length}</b> авторлық шағын сабақ</span><span><b>${builtinLessons().reduce((a,l)=>a+l.questions.length,0)}</b> түсіндірмелі тест сұрағы</span><span><b>${CHALLENGES.length}</b> олимпиадалық есеп</span><span><b>${LAB_IDS.length}</b> интерактивті зертхана</span><span><b>${SUBJECTS.length}</b> пән: ${SUBJECTS.map(s=>esc(s.short)).join(', ')}</span></div><a class="btn" href="#teacher">Мұғалім ретінде қосылу <span>↗</span></a></div><div class="panel"><h3>Жасанды интеллект және адам</h3><p>Жоба ЖИ көмегімен сайт жасау идеясын көрсетеді: идеяны құрылымдау, код әзірлеу және оқу тәжірибесін құрастыру. ЖИ ұсынған мазмұнды адам тексеріп, жетілдіруі керек.</p><p>Сайт ішінде сыртқы ЖИ чат қызметі қосылмаған. Интерактивтер браузерде орындалады. Мұндағы материалдар — ықшам қосымша жаттығулар; толық оқулық пен ресми емтихан базасын алмастырмайды.</p><a class="btn text" href="#lesson/ai">ЖИ-ді саналы қолдануды үйрен →</a><div class="tech-credits"><a href="https://github.com/juliangarnier/anime" target="_blank" rel="noopener noreferrer">Anime.js ↗</a><a href="https://github.com/micku7zu/vanilla-tilt.js" target="_blank" rel="noopener noreferrer">Vanilla Tilt ↗</a><a href="https://github.com/catdad/canvas-confetti" target="_blank" rel="noopener noreferrer">Canvas Confetti ↗</a><a href="https://github.com/rsms/inter" target="_blank" rel="noopener noreferrer">Inter қарпі ↗</a></div><div class="repository-note">Анимациялар ашық кодты кітапханалармен жасалды. Лицензиялар жоба файлдарында сақталған.</div></div></section>`;}
function missing(){return '<section class="panel center"><h1>Бет табылмады</h1><p>Мәзірден қажетті бөлімді таңда.</p><a class="btn" href="#home">Басты бетке →</a></section>';}
function route(){const [page,arg]=(location.hash.slice(1)||'home').split('/');return {page,arg:arg?decodeURIComponent(arg):arg};}
function render(){if(window.BilimMotion)window.BilimMotion.beforeRender();clearInterval(routeTimer);clearInterval(sortTimer);sortTimer=null;if(robotTimer){clearInterval(robotTimer);robotTimer=null;robotRunning=false;}const {page,arg}=route();if(page==='courses'&&arg&&(arg==='all'||SUBJECTS.some(s=>s.id===arg))&&courseSubject!==arg){courseSubject=arg;courseGrade=0;}const active={lesson:'courses',lab:'labs',result:'exam','exam-run':'exam',join:'progress'}[page]||page;const teacherAuth=window.BilimAPI?.auth()?.role==='teacher';$('#nav').innerHTML=PAGES.map(([id,t])=>`<a href="#${id}" class="${id===active?'active':''}" ${id===active?'aria-current="page"':''}>${icon(id)}${t}${id==='labs'?`<span class="nav-badge">${LAB_IDS.length}</span>`:''}${id==='teacher'&&teacherAuth?'<span class="nav-badge on">●</span>':''}</a>`).join('');$('#breadcrumb').textContent=PAGES.find(p=>p[0]===active)?.[1]||'Бет';document.title=`${$('#breadcrumb').textContent} · Білім PRO`;updateProfileChip();const T=window.BilimTeacher;const views={home,courses,olympiad,exam:examIntro,'exam-run':examView,result:resultView,labs:labHome,progress,about,lesson:()=>lessonView(arg),lab:()=>labView(arg),teachers:()=>T?T.teachersView():missing(),teacher:()=>T?T.view(arg):missing(),join:()=>T?T.joinView(arg):missing()};$('#main').innerHTML=(views[page]||missing)();if(page==='exam-run'&&exam){updateTimer();if(exam)routeTimer=setInterval(updateTimer,1000);}if(page==='courses')updateCourseCount();$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');if(window.BilimArt)window.BilimArt.decorate(page,arg);if(T&&['teachers','teacher','join'].includes(page))T.mount(page,arg);if(window.BilimMotion)window.BilimMotion.mount({page,arg});}
function updateProfileChip(){const chip=$('.top-profile');if(!chip)return;const a=window.BilimAPI?.auth();if(a?.role==='teacher'){chip.textContent=(a.teacher?.name||'М')[0];chip.href='#teacher';chip.setAttribute('aria-label','Мұғалім кабинеті');chip.classList.add('teacher');}else{chip.textContent=a?.role==='student'?(a.student?.name||'Б')[0]:'Б';chip.href='#progress';chip.setAttribute('aria-label','Менің жетістіктерім');chip.classList.remove('teacher');}}
function updateCourseCount(){if($('#course-count'))$('#course-count').textContent=`${courseList().length} сабақ табылды`;}
const closeButton=()=>'<button class="icon-btn" data-action="modal-close" aria-label="Жабу">×</button>';
function openModal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();if(window.BilimMotion)window.BilimMotion.modal();}
function startQuiz(id){const l=LESSONS.find(l=>l.id===id);if(!l)return;quiz={id,pos:0,score:0,answered:false,questions:l.questions.map(q=>({...q,options:shuffle(q.options)}))};showQuiz();}
function showQuiz(){const q=quiz.questions[quiz.pos],n=quiz.questions.length;openModal(`<div class="modal-top"><h2>Біліміңді тексер</h2>${closeButton()}</div><div class="quiz-head"><span>${quiz.pos+1} / ${n} сұрақ</span><span>${quiz.score} дұрыс жауап</span></div><div class="progress-bar"><span style="width:${quiz.pos/n*100}%"></span></div><h3 class="quiz-question">${esc(q.q)}</h3><div class="quiz-options">${q.options.map((o,i)=>`<button class="option" data-quiz-answer="${i}"><span class="letter">${'ABCD'[i]}</span>${esc(o)}</button>`).join('')}</div><div id="quiz-feedback" aria-live="polite"></div><button class="btn" id="quiz-next" data-action="quiz-next" disabled>${quiz.pos===n-1?'Нәтижені көру':'Келесі сұрақ'} →</button>`);}
function quizAnswer(i){if(!quiz||quiz.answered)return;quiz.answered=true;const q=quiz.questions[quiz.pos],right=q.options[i]===q.answer;if(right)quiz.score++;$$('[data-quiz-answer]').forEach(b=>{const n=Number(b.dataset.quizAnswer);b.disabled=true;if(q.options[n]===q.answer)b.classList.add('correct');else if(n===i)b.classList.add('wrong');});$('#quiz-feedback').innerHTML=`<div class="feedback ${right?'correct':'wrong'}">${right?'✓ Дұрыс!':'○ Қайта ойлануға мүмкіндік.'} ${esc(q.explain)}</div>`;$('#quiz-next').disabled=false;$('#quiz-next').focus({preventScroll:true});}
function quizNext(){if(!quiz?.answered)return;const n=quiz.questions.length;if(quiz.pos<n-1){quiz.pos++;quiz.answered=false;showQuiz();return;}const old=state.quiz[quiz.id]||0;state.quiz[quiz.id]=Math.max(old,quiz.score);save();openModal(`<div class="modal-top"><h2>Сабақ тесті аяқталды</h2>${closeButton()}</div><div class="center"><div class="result-score">${quiz.score}<small> / ${n}</small></div><p>${quiz.score===n?'Керемет! Тақырыпты жақсы меңгердің.':'Түсіндірмелерді қайталап, тағы байқап көр.'}</p><div class="row" style="justify-content:center"><button class="btn lime" data-quiz="${quiz.id}">Қайта орындау ↻</button><button class="btn secondary" data-action="quiz-close">Сабаққа оралу</button></div></div>`);if(quiz.score===n&&window.BilimMotion)window.BilimMotion.celebrate('quiz');}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function startExamRoute(){if(!exam)createExam(examSubject);if(location.hash==='#exam-run')render();else location.hash='#exam-run';}
async function loadTeacherLessons(){if(!window.BilimAPI)return;try{const {lessons}=await window.BilimAPI.request('GET','/lessons');const before=LESSONS.filter(l=>l.custom).map(l=>l.id+l.updated).join();for(let i=LESSONS.length-1;i>=0;i--)if(LESSONS[i].custom)LESSONS.splice(i,1);LESSONS.push(...lessons.map(l=>({...l,custom:true,raw:l,questions:l.questions.map(q=>({q:q.q,answer:q.answer,options:[q.answer,...q.wrong],explain:q.explain}))})));if(before===LESSONS.filter(l=>l.custom).map(l=>l.id+l.updated).join())return;const {page,arg}=route();if(['home','courses','about'].includes(page)||(page==='lesson'&&CUSTOM_ID.test(arg||'')))render();}catch{}}
function handleAction(action){switch(action){
case'modal-close':$('#modal').close();break;
case'menu-close':$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');break;
case'quiz-close':$('#modal').close();render();break;
case'print':window.print();break;
case'quiz-next':quizNext();break;
case'hint':$('#challenge-help').innerHTML=`<div class="feedback">${esc(CHALLENGES[challengeId].hint)}</div>`;break;
case'solution':challengeRevealed=true;$('#challenge-help').innerHTML=`<div class="feedback">${esc(CHALLENGES[challengeId].solution)}</div><pre class="code-block">${esc(CHALLENGES[challengeId].code)}</pre><p class="notice">Бұл — шешім үлгісі. Код осы жерде орындалмайды. Өзің тексеру үшін Python ортасына көшір.</p>`;break;
case'exam-start':startExamRoute();break;
case'exam-prev':if(exam&&exam.pos>0){exam.pos--;keepExam();render();}break;
case'exam-next':if(exam&&exam.pos<exam.questions.length-1){exam.pos++;keepExam();render();}break;
case'exam-finish':finishExam();break;
case'exam-confirm':commitExam();break;
case'exam-retry':createExam(lastResult?.subject||examSubject);startExamRoute();break;
case'binary-mission':binaryTarget=1+Math.floor(Math.random()*255);binaryWon=false;bits=Array(8).fill(0);refreshLab();break;
case'binary-reset':bits=Array(8).fill(0);binaryWon=false;refreshLab();break;
case'sort-next':sortNext();break;
case'sort-prev':if(sortIndex>0){clearInterval(sortTimer);sortTimer=null;sortIndex--;refreshLab();}break;
case'sort-play':if(sortTimer){clearInterval(sortTimer);sortTimer=null;refreshLab();}else{sortTimer=setInterval(sortNext,450);refreshLab();}break;
case'sort-reset':clearInterval(sortTimer);sortTimer=null;makeSort();refreshLab();break;
case'pixel-clear':pixels.fill(0);refreshLab();break;
case'pixel-example':pixels=['01100110','11111111','11111111','11111111','01111110','00111100','00011000','00000000'].join('').split('').map(Number);refreshLab();break;
case'pixel-download':if(pixels.some(Boolean))labAward('pixels');download('bilim-pro-pixel.svg',`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80"><rect width="80" height="80" fill="#f5f6f2"/>${pixels.map((v,i)=>v?`<rect x="${i%8*10}" y="${Math.floor(i/8)*10}" width="10" height="10" fill="#193c3a"/>`:'').join('')}</svg>`,'image/svg+xml');break;
case'robot-run':runRobot();break;
case'robot-undo':if(!robotRunning){robotCommands.pop();robotPosition=[0,5];refreshLab();}break;
case'robot-clear':if(!robotRunning){robotCommands=[];robotPosition=[0,5];refreshLab();}break;
case'graph-mission':graphMission();refreshLab();break;
case'graph-reset':graph={k:1,b:0,target:null,won:false};refreshLab();break;
case'ohm-mission':ohmMission();refreshLab();break;
case'ohm-reset':ohm={u:12,r:6,target:null,won:false};refreshLab();break;
case'sync-now':if(window.BilimAPI){window.BilimAPI.request('POST','/progress',{progress:progressSummary()}).then(()=>{toast('Прогресс мұғалімге жіберілді.');render();}).catch(e=>toast(e.message));}break;
case'leave-class':openModal(`<div class="modal-top"><h2>Сыныптан шығу</h2>${closeButton()}</div><p>Осы құрылғы сыныптан ажыратылады. Жеке прогресің браузерде қалады. Қайта қосылу үшін сол кодты, есімді және PIN-кодты енгіз.</p><div class="row"><button class="btn danger" data-action="leave-confirm">Иә, шығу</button><button class="btn secondary" data-action="modal-close">Бас тарту</button></div>`);break;
case'leave-confirm':window.BilimAPI.setAuth(null);$('#modal').close();loadTeacherLessons();render();toast('Сыныптан шықтың.');break;
case'export':download('Bilim_PRO_progress.json',JSON.stringify(state,null,2),'application/json');break;
case'import':$('#import-file').click();break;
case'reset':openModal(`<div class="modal-top"><h2>Прогресті тазалау</h2>${closeButton()}</div><p>Осы браузердегі сабақтар, жетістіктер және тест тарихы өшеді. Қажет болса, алдымен JSON көшірмесін жүктеп ал.</p><div class="row"><button class="btn danger" data-action="reset-confirm">Иә, тазалау</button><button class="btn secondary" data-action="modal-close">Бас тарту</button></div>`);break;
case'reset-confirm':state=fresh();exam=null;lastResult=null;keepExam();save();$('#modal').close();render();toast('Прогресс тазаланды. Жаңа бастама!');break;
case'import-confirm':if(pendingImport){state=pendingImport;pendingImport=null;save();$('#modal').close();render();toast('Прогресс импортталды.');}break;
}}
let pendingImport=null;
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.action){handleAction(b.dataset.action);return;}if(b.id==='menu-toggle'){const open=$('#sidebar').classList.toggle('open');b.setAttribute('aria-expanded',String(open));return;}if(b.dataset.subject!==undefined&&b.dataset.scope){const subject=b.dataset.subject,scope=b.dataset.scope;if(scope==='home'){state.subject=subject;save();render();}if(scope==='courses'){courseGrade=0;if(location.hash==='#courses/'+subject){courseSubject=subject;render();}else location.hash='#courses/'+subject;}if(scope==='olympiad'){olympSubject=subject;olympGrade=0;render();}if(scope==='exam'){examSubject=subject;render();}return;}if(b.dataset.grade!==undefined){const grade=Number(b.dataset.grade),scope=b.dataset.scope;if(scope==='home'){state.grade=grade;save();}if(scope==='courses')courseGrade=grade;if(scope==='olympiad')olympGrade=grade;render();return;}if(b.dataset.openGrade){e.preventDefault();courseGrade=Number(b.dataset.openGrade);if(location.hash==='#courses')render();else location.hash='#courses';return;}if(b.dataset.complete){const id=b.dataset.complete;if(!state.completed.includes(id)){state.completed.push(id);save();render();toast('+20 XP · Сабақ оқылды!');}return;}if(b.dataset.quiz){startQuiz(b.dataset.quiz);return;}if(b.dataset.quizAnswer!==undefined){quizAnswer(Number(b.dataset.quizAnswer));return;}if(b.dataset.challenge!==undefined){openChallenge(Number(b.dataset.challenge));return;}if(b.dataset.examAnswer!==undefined&&exam){if(Date.now()>=exam.deadline){finishExam(true);return;}exam.answers[exam.pos]=Number(b.dataset.examAnswer);keepExam();render();return;}if(b.dataset.examPos!==undefined&&exam){exam.pos=Number(b.dataset.examPos);keepExam();render();return;}if(b.dataset.bit!==undefined){const i=Number(b.dataset.bit);bits[i]=1-bits[i];if(binaryTarget!==null&&parseInt(bits.join(''),2)===binaryTarget){binaryWon=true;labAward('binary');}else binaryWon=false;refreshLab();const next=$(`[data-bit="${i}"]`);next?.focus();return;}if(b.dataset.pixel!==undefined){const i=Number(b.dataset.pixel);pixels[i]=1-pixels[i];refreshLab();$(`[data-pixel="${i}"]`)?.focus();return;}if(b.dataset.command&&!robotRunning){if(robotCommands.length>=30){toast('Ең көбі 30 команда. Артық команданы өшір.');return;}robotCommands.push(b.dataset.command);robotPosition=[0,5];refreshLab();return;}});
document.addEventListener('submit',e=>{if(e.target.id==='challenge-form'){e.preventDefault();checkChallenge();}});
document.addEventListener('input',e=>{if(e.target.id==='course-search'){query=e.target.value;if(window.BilimMotion)window.BilimMotion.beforeRender();$('#course-results').innerHTML=courseCards();updateCourseCount();if(window.BilimMotion)window.BilimMotion.mount({page:'courses'});return;}const r=e.target.dataset?.range;if(!r)return;const v=Number(e.target.value);if(r==='k'||r==='b'){graph[r]=v;const t=graph.target,was=graph.won;graph.won=!!t&&graph.k===t.k&&graph.b===t.b;updateGraph();if(graph.won&&!was)labAward('graph');}if(r==='u'||r==='r'){ohm[r]=v;const was=ohm.won;ohm.won=ohm.target!==null&&Math.abs(ohm.u/ohm.r-ohm.target)<1e-9;updateOhm();if(ohm.won&&!was)labAward('ohm');}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files[0];if(!file)return;if(file.size>200000){toast('Файл тым үлкен. Прогресс JSON файлын таңда.');return;}try{const raw=JSON.parse(await file.text());if(!raw||raw.version!==1||!Array.isArray(raw.completed)||!Array.isArray(raw.solved))throw Error();pendingImport=cleanState(raw);openModal(`<div class="modal-top"><h2>Прогресті импорттау</h2>${closeButton()}</div><p>Файлда ${pendingImport.completed.length} оқылған сабақ, ${pendingImport.solved.length} шешілген есеп және ${pendingImport.history.length} тест нәтижесі бар. Импорт қазіргі прогресті осы деректермен алмастырады.</p><div class="row"><button class="btn" data-action="import-confirm">Импорттау</button><button class="btn secondary" data-action="modal-close">Бас тарту</button></div>`);}catch{toast('Файлды оқу мүмкін болмады. Білім PRO прогресс файлын таңда.');}e.target.value='';});
window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
render();
if(window.BilimAPI){window.BilimAPI.detect().then(()=>{loadTeacherLessons();if(!['lab','exam-run'].includes(route().page))render();});}
